def is_decimal(value: str) -> bool:
    # Check if the string matches a decimal number with exactly two decimal places
    import re
    pattern = r'^-?\d+\.\d{2}$'
    return bool(re.match(pattern, value))

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False

    first_char = s[0]
    second_char = None

    # Find second distinct character different from first_char
    for ch in s:
        if ch != first_char:
            second_char = ch
            break

    # If no second distinct character found or both chars are same, return False
    if second_char is None:
        return False

    # Check that s contains only these two characters
    for ch in s:
        if ch != first_char and ch != second_char:
            return False

    # Check that characters alternate correctly:
    # characters at even indices are the same character (either first_char or second_char)
    # characters at odd indices are the other character
    # But it could be that s starts with either first_char or second_char
    # So we check both possible patterns:

    def check_pattern(start_char, alt_char):
        for i, ch in enumerate(s):
            expected_char = start_char if i % 2 == 0 else alt_char
            if ch != expected_char:
                return False
        return True

    return check_pattern(first_char, second_char) or check_pattern(second_char, first_char)

def len_log(words):
