def count_nums(arr):
    def sum_signed_digits(num):
        s = str(num)
        if s[0] == '-':
            # first digit is negative
            total = -int(s[1])
            # add remaining digits positively
            for ch in s[2:]:
                total += int(ch)
            return total
        else:
            return sum(int(ch) for ch in s)

    count = 0
    for num in arr:
        # count if sum_signed_digits(num) > 0, regardless of num sign
        if sum_signed_digits(num) > 0:
            count += 1
    return count

